const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
  const page = await context.newPage();

  // Login
  await page.goto('http://localhost:3000/login');
  await page.fill('#email-input', 'blairerickson@gmail.com');
  await page.fill('#password-input', 'pearlos2026');
  await page.click('button[type="submit"]');
  await page.waitForTimeout(3000);

  // Notes with MagicWandButton
  await page.goto('http://localhost:3000/notes');
  await page.waitForTimeout(2000);
  await page.screenshot({
    path: '/workspace/nia-universal/qa/workflow-02-notes-with-wand.png',
    fullPage: true,
  });

  console.log('Screenshot captured: qa/workflow-02-notes-with-wand.png');
  await browser.close();
})();
EOF

